                </RoleGuard>
              }
            />
            <Route
              path="/admin/users"
              element={
                <RoleGuard allowedRoles={['ROLE_SYSTEM_ADMIN']}>
                  <UserManagementPage />
                </RoleGuard>
              }
            />
          </Routes>
        </Content>
      </Layout>
    </Layout>
  );
}

export default App;

