            <Route
              path="/dashboard"
              element={
                <RoleGuard allowedRoles={['ROLE_USER']}>
                  <DashboardPage />
                </RoleGuard>
              }
            />
            <Route
              path="/admin/users"
              element={
                <RoleGuard allowedRoles={['ROLE_SYSTEM_ADMIN']}>
                  <UserManagementPage />
                </RoleGuard>
              }
            />
            <Route
              path="/admin/firms"
              element={
                <RoleGuard allowedRoles={['ROLE_SYSTEM_ADMIN']}>
                  <FirmManagementPage />
                </RoleGuard>
              }
            />
            <Route
              path="/practitioners"
              element={
