                  <PractitionerListPage />
                </RoleGuard>
              }
            />
            <Route
              path="/practitioners/:id"
              element={
                <RoleGuard allowedRoles={['ROLE_USER']}>
                  <PractitionerDetailPage />
                </RoleGuard>
              }
            />
          </Routes>
        </Content>
      </Layout>
    </Layout>
  );
}

export default App;

