+        $client->request('POST', '/api/v1/auth/login', server: ['CONTENT_TYPE' => 'application/json'], content: json_encode([
+            'username' => $username,
+            'password' => $password,
+        ], JSON_THROW_ON_ERROR));
+        $data = json_decode((string) $client->getResponse()->getContent(), true, flags: JSON_THROW_ON_ERROR);
+        return $data['token'];
+    }
+}
