+            ->join('p.firm', 'f')
+            ->orderBy('s.updatedAt', 'DESC');
+
+        if ($state) {
+            $qb->andWhere('s.currentState = :state')->setParameter('state', $state);
+        }
+
+        return $qb->getQuery()->getResult();
+    }
+}
